CREATE TABLE IF NOT EXISTS `{prefix}_spam_whitelist` ( `id` int(11) NOT NULL AUTO_INCREMENT, `data` varchar(255) NOT NULL, `type` enum('ip','email','domain') NOT NULL DEFAULT 'ip', `note` varchar(255) NOT NULL, PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET={charset};
